package net.officefloor.hq.app.voidreason;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing and adding the void reasons on a sheet. */
@RestController
@RequestMapping("/api/void-reasons")
public class VoidReasonController {

    public record ListVoidReasonsRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record AddVoidReasonRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull @Size(max = 200) String reason) {
    }

    public record VoidReasonResponse(long id, String reason) {
    }

    private static VoidReasonResponse response(VoidReason reason) {
        return new VoidReasonResponse(reason.getId(), reason.getReason());
    }

    private final VoidReasonService service;

    public VoidReasonController(VoidReasonService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<VoidReasonResponse> list(@Valid @RequestBody ListVoidReasonsRequest req) {
        return service.list(req.sheet().trim()).stream().map(VoidReasonController::response).toList();
    }

    @PostMapping("/add")
    public VoidReasonResponse add(@Valid @RequestBody AddVoidReasonRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.reason()));
    }
}
package net.officefloor.hq.app.voidreason;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A reason a claim on the sheet may be voided with: a text, at most once. */
@Entity
@Table(name = "void_reason")
public class VoidReason {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false)
    private String reason;

    protected VoidReason() {
    }

    public VoidReason(String sheetId, String reason) {
        this.sheetId = sheetId;
        this.reason = reason;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getReason() {
        return reason;
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    /** The sheet's void reasons, in the order they were added. */
    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    boolean existsBySheetId(String sheetId);

    boolean existsBySheetIdAndReason(String sheetId, String reason);
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's void reasons: texts added on the screen, each at most once. While the sheet has any,
 * a claim is voided only with one of them (see {@link #refuseUnlessListed}).
 */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
        this.roles = roles;
    }

    @Transactional(readOnly = true)
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a void reason (trimmed); a blank one is refused (422), one already on the list (409). */
    @Transactional
    public VoidReason add(String sheetId, String user, String reason) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "Enter a void reason.");
        }
        // hold the sheet so the same reason added twice at the same moment is checked one after the other
        sheetRows.findLockedById(sheetId);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That reason is already on the list.");
        }
        VoidReason added;
        try {
            added = reasons.saveAndFlush(new VoidReason(sheetId, text));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That reason is already on the list.");
        }
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + added.getReason());
        return added;
    }

    /**
     * The reason to void a claim with, trimmed (none when not given): refused (422) when the sheet
     * has void reasons and none of them is given, or when one is given that is not on the list.
     */
    @Transactional(readOnly = true)
    public String refuseUnlessListed(String sheetId, String reason) {
        String text = reason == null || reason.isBlank() ? null : reason.trim();
        if (text == null) {
            if (reasons.existsBySheetId(sheetId)) {
                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                        "Choose a reason to void this claim.");
            }
            return null;
        }
        if (!reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "That void reason is not on the list.");
        }
        return text;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

// The sheet's void reasons, in the order they were added, re-read from the store every time a
// sheet is loaded. While the list is not empty a claim is voided only with one of them; the
// summary counts the VOID claims voided with each.
export interface VoidReason {
  id: number;
  reason: string;
}

@Injectable({ providedIn: 'root' })
export class VoidReasons {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly list = signal<VoidReason[]>([]);
  /** Set when the list could not be read from the store. */
  readonly loadError = signal<string | null>(null);

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.list.set([]);
      this.loadError.set(null);
      if (sheet) {
        void this.fetch(sheet);
      }
    });
  }

  private async fetch(sheet: string): Promise<void> {
    try {
      const list = await firstValueFrom(this.http.post<VoidReason[]>('/api/void-reasons/list', { sheet }));
      if (this.session.sheet() === sheet) this.list.set(list);
    } catch {
      this.loadError.set('Could not read the void reasons on this sheet.');
    }
  }

  /** Add a reason (trimmed) to the list; the store refuses a blank or repeated one. */
  async add(reason: string): Promise<void> {
    const sheet = this.session.sheet();
    const added = await firstValueFrom(
